package net.officefloor.hq.app.asof;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * A request handler that only reads the sheet although it is not a GET (loading a sheet): it is shown
 * as of the user's as-of date like any read, not refused like a change.
 */
@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
public @interface AsOfRead {}
package net.officefloor.hq.app.asof;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.springframework.http.HttpMethod;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import org.springframework.web.util.ContentCachingResponseWrapper;

/**
 * Records a sheet in its {@link SheetHistory} after each change to it that went through (marked by
 * {@link AsOfGuard}), before the answer goes back: the user's next change cannot overtake it.
 */
@Component
public class SheetHistoryFilter extends OncePerRequestFilter {

    /** The request attribute naming the sheet a change that went through was made to. */
    static final String CHANGED = SheetHistoryFilter.class.getName() + ".changed";

    private final SheetHistory history;

    public SheetHistoryFilter(SheetHistory history) {
        this.history = history;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())
                || !request.getRequestURI().startsWith("/api/sheets/");
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        ContentCachingResponseWrapper held = new ContentCachingResponseWrapper(response);
        try {
            chain.doFilter(request, held);
            if (request.getAttribute(CHANGED) instanceof String sheetId) history.capture(sheetId);
        } finally {
            held.copyBodyToResponse();
        }
    }
}
package net.officefloor.hq.app.asof;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.locks.ReentrantLock;
import net.officefloor.hq.app.sheet.SheetParentRepository;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionStatus;
import org.springframework.transaction.support.DefaultTransactionDefinition;
import org.springframework.web.method.HandlerMethod;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/**
 * The as-of view, which belongs to the user's screen: a request to a sheet carrying an
 * {@value #HEADER} date is shown as the sheet stood at the end of that date, and a change asked
 * with one is refused before anything is written. Every other change made to a sheet that has gone
 * through is marked for {@link SheetHistoryFilter} to record in its {@link SheetHistory}.
 *
 * <p>A read as of a date runs in a transaction that puts the sheet back as it stood then, with that
 * date as its today (with every descendant sheet too, for a read marked {@link AsOfTree}), and is rolled
 * back once the read is answered, so it changes nothing and audits nothing.
 */
@Configuration
public class AsOfGuard implements WebMvcConfigurer, HandlerInterceptor {

    /** The request header carrying the user's as-of date (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private static final String VIEW = AsOfGuard.class.getName() + ".view";

    /** A read as of a date under way: its transaction and the locks it holds on its sheets. */
    private record View(TransactionStatus transaction, List<ReentrantLock> locks) {}

    private final SheetHistory history;
    private final SheetParentRepository parents;
    private final PlatformTransactionManager transactions;

    public AsOfGuard(SheetHistory history, SheetParentRepository parents, PlatformTransactionManager transactions) {
        this.history = history;
        this.parents = parents;
        this.transactions = transactions;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (!(handler instanceof HandlerMethod method)) return true;
        String sheetId = sheetId(request);
        String header = request.getHeader(HEADER);
        if (sheetId == null || header == null || header.isBlank()) return true;
        if (!isRead(request) && !method.hasMethodAnnotation(AsOfRead.class)) throw new AsOfRefusedException();
        LocalDate asOf;
        try {
            asOf = LocalDate.parse(header.trim());
        } catch (DateTimeParseException e) {
            throw new AsOfRefusedException();
        }
        // a sheet never started is started as usual
        if (!history.exists(sheetId)) return true;
        // a read over the tree puts back every descendant too, each locked after its ancestors
        List<String> restored = new ArrayList<>(List.of(sheetId));
        if (method.hasMethodAnnotation(AsOfTree.class)) {
            for (String descendant : parents.descendantsOf(sheetId)) if (history.exists(descendant)) restored.add(descendant);
        }
        List<ReentrantLock> held = new ArrayList<>();
        TransactionStatus transaction = null;
        try {
            for (String sheet : restored) {
                ReentrantLock lock = history.lock(sheet);
                lock.lock();
                held.add(lock);
            }
            transaction = transactions.getTransaction(new DefaultTransactionDefinition());
            for (String sheet : restored) history.restore(sheet, asOf);
        } catch (RuntimeException e) {
            if (transaction != null) transactions.rollback(transaction);
            unlock(held);
            throw e;
        }
        request.setAttribute(VIEW, new View(transaction, held));
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) {
        if (request.getAttribute(VIEW) instanceof View view) {
            request.removeAttribute(VIEW);
            try {
                transactions.rollback(view.transaction());
            } finally {
                unlock(view.locks());
            }
            return;
        }
        if (isRead(request) || ex != null || response.getStatus() >= 400) return;
        String sheetId = sheetId(request);
        if (sheetId != null) request.setAttribute(SheetHistoryFilter.CHANGED, sheetId);
    }

    private static void unlock(List<ReentrantLock> held) {
        for (int i = held.size() - 1; i >= 0; i--) held.get(i).unlock();
    }

    private static boolean isRead(HttpServletRequest request) {
        return HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod());
    }

    /** The sheet the request is for: its sheetId path variable, or the id of a request to the sheet itself. */
    private static String sheetId(HttpServletRequest request) {
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (vars == null) return null;
        return vars.getOrDefault("sheetId", vars.get("id"));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.asof.AsOfRead;
import net.officefloor.hq.app.setting.OpenToViewer;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingController;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    /**
     * A sheet as the screen shows it; the floor, the terms, the late percent and the cap are those in
     * force on its today: the floor has two decimals, the terms are in days, the late percent has two
     * decimals; the policy date is null when blank (the sheet's today); the cap has two decimals, null
     * when none; dated has every value recorded for its dated settings, by key; archived is whether a
     * steward has archived it; last batch is the number of its last bulk settle batch, null when none; the review SLA is in days, null when none;
     * the score mid and score high are whole numbers, null when blank;
     * role is the role the signed-in user acts in on it (clerk, steward, viewer or restricted) on its today.
     */
    public record SheetView(String id, LocalDate today, String floor, int terms, String latePct,
            LocalDate policyDate, String cap, Map<String, List<SettingController.DatedView>> dated,
            boolean archived, Integer lastBatch, Integer reviewSla, String role, Integer scoreMid,
            Integer scoreHigh) {
        static SheetView of(Sheet sheet, Role role) {
            LocalDate today = sheet.getToday();
            return new SheetView(sheet.getId(), today, sheet.floorOn(today).toPlainString(),
                    sheet.termsOn(today), sheet.latePctOn(today).toPlainString(), sheet.getPolicyDate(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    SettingController.datedViews(sheet.getDated()), sheet.isArchived(),
                    sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch(), sheet.getReviewSla(),
                    role.label(), sheet.getScoreMid(), sheet.getScoreHigh());
        }
    }

    public record TodayRequest(@NotNull LocalDate today) {}

    /** The id of the sheet to clone this one to: one never used. */
    public record CloneRequest(@NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String to) {}

    /** A clone made: the id of the sheet it was made to. */
    public record CloneView(String to) {}

    private final SheetService service;
    private final SheetCloneService clones;
    private final SettingService settings;

    public SheetController(SheetService service, SheetCloneService clones, SettingService settings) {
        this.service = service;
        this.clones = clones;
        this.settings = settings;
    }

    /** The sheet as the user is shown it, with the role they act in on it. */
    private SheetView view(Sheet sheet, String user) {
        return SheetView.of(sheet, settings.roleOf(sheet.getId(), user.trim()));
    }

    /** Load (or start) a sheet by id for the signed-in user. */
    @OpenToViewer
    @AsOfRead
    @PostMapping("/{id}/load")
    public SheetView load(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.load(id, user.trim()), user);
    }

    /** Change the sheet's today. */
    @PutMapping("/{id}/today")
